        { en: "regular customer", vi: "khách quen" },
        { en: "fresh, hot and clean", vi: "tươi, nóng và sạch" },
        { en: "less than a bus ticket", vi: "rẻ hơn một vé xe buýt" },
        { en: "start the day", vi: "bắt đầu ngày mới" }
