    pushOld(48, old);
  old = repVocab(100, 17, "talon", {"w":"paw","ipa":"/pɔː/","vi":"bàn chân (thú)","col":"the dog's paw","ex":"The dog hurt its paw.","exv":"Con chó bị đau chân."});
