  old = repVocab(101, 2, "spotless", {"w":"tidy","ipa":"/ˈtaɪdi/","vi":"gọn gàng","col":"a tidy room","ex":"Keep your room tidy.","exv":"Giữ phòng của bạn gọn gàng."});
