// IELTS mở rộng đợt 30/10 — ngữ pháp 10 trạm, Đọc 20 bài, Nghe dài 10 bài, drills Viết 20. Tự soạn 100%, tiếng Việt giải thích.
var IELTS_GRAMMAR_EXPAND = [
{ fam: "Thì", level: "Band 5,0", name: "Hiện tại hoàn thành và quá khứ đơn", hook: "“I have lived here for 3 years.” — Tôi đã sống ở đây được 3 năm (và vẫn đang sống).", examples: ["I have lived in Hanoi for 3 years. — Tôi đã sống ở Hà Nội được 3 năm.", "I lived in Hanoi in 2020. — Tôi đã sống ở Hà Nội năm 2020.", "She has just finished her homework. — Cô ấy vừa làm xong bài tập."], explain: "Ví dụ trước: 'I have lived in Hanoi for 3 years.' (Tôi đã sống ở Hà Nội được 3 năm — vẫn đang sống.) 'I lived in Hanoi in 2020.' (Tôi đã sống ở Hà Nội năm 2020 — đã xong.) Quy tắc: hiện tại hoàn thành (have/has + phân từ 2) dùng với for/since, ever, never, just, already, yet — hành động liên quan đến hiện tại; quá khứ đơn dùng với mốc thời gian đã xong (yesterday, last year, in 2020).",
  quiz: [
  { q: "Điền đúng: 'I ___ in Hanoi for 3 years.'", o: ["have lived", "lived", "live"], a: 0, why: "For 3 years → hiện tại hoàn thành: have lived." },
  { q: "Điền đúng: 'I ___ in Hanoi in 2020.'", o: ["have lived", "lived", "live"], a: 1, why: "In 2020 là mốc đã xong → quá khứ đơn: lived." },
  { q: "Điền đúng: 'She has ___ finished her homework.'", o: ["just", "yesterday", "last week"], a: 0, why: "Just đi với hiện tại hoàn thành: has just finished." },
  { q: "Điền đúng: 'We ___ to Da Nang last summer.'", o: ["have gone", "went", "go"], a: 1, why: "Last summer → quá khứ đơn: went." },
  { q: "Điền đúng: 'Have you ___ seen this film?'", o: ["ever", "yesterday", "last night"], a: 0, why: "Ever đi với hiện tại hoàn thành trong câu hỏi." },
  { q: "Câu nào đúng?", o: ["I have seen him yesterday.", "I saw him yesterday.", "I see him yesterday."], a: 1, why: "Yesterday → quá khứ đơn: saw." }
  ] },
{ fam: "Câu bị động", level: "Band 5,5", name: "Câu bị động các thì cơ bản", hook: "“The book was written by Lan.” — Cuốn sách được viết bởi Lan.", examples: ["The book was written by Lan. — Cuốn sách được viết bởi Lan.", "The house is cleaned every day. — Ngôi nhà được dọn mỗi ngày.", "The letter will be sent tomorrow. — Bức thư sẽ được gửi vào ngày mai."], explain: "Ví dụ trước: 'The book was written by Lan.' (Cuốn sách được viết bởi Lan.) 'The house is cleaned every day.' (Ngôi nhà được dọn mỗi ngày.) Quy tắc: bị động = be + phân từ 2. Hiện tại đơn: is/are + V-ed; quá khứ đơn: was/were + V-ed; tương lai: will be + V-ed. Dùng khi không quan tâm ai làm, hoặc người làm không quan trọng.",
  quiz: [
  { q: "Điền đúng: 'The book ___ by Lan.'", o: ["was written", "wrote", "writes"], a: 0, why: "Bị động quá khứ: was written." },
  { q: "Điền đúng: 'The house ___ every day.'", o: ["is cleaned", "cleans", "cleaned"], a: 0, why: "Bị động hiện tại: is cleaned." },
  { q: "Điền đúng: 'The letter ___ tomorrow.'", o: ["will be sent", "sends", "sent"], a: 0, why: "Bị động tương lai: will be sent." },
  { q: "Câu bị động của 'Lan cooks rice.' là:", o: ["Rice is cooked by Lan.", "Rice cooks Lan.", "Lan is cooked rice."], a: 0, why: "Rice is cooked by Lan." },
  { q: "Điền đúng: 'English ___ in many countries.'", o: ["is spoken", "speaks", "spoke"], a: 0, why: "Bị động hiện tại: is spoken." },
  { q: "Điền đúng: 'The bridge ___ in 2020.'", o: ["was built", "builds", "is built"], a: 0, why: "In 2020 → bị động quá khứ: was built." }
  ] },
{ fam: "Câu tường thuật", level: "Band 6,0", name: "Câu tường thuật cơ bản", hook: "“He said he was tired.” — Anh ấy nói rằng anh ấy mệt.", examples: ["He said he was tired. — Anh ấy nói rằng anh ấy mệt.", "She told me she lived in Da Nang. — Cô ấy nói với tôi rằng cô ấy sống ở Đà Nẵng.", "They asked if I liked tea. — Họ hỏi tôi có thích trà không."], explain: "Ví dụ trước: Lan nói: 'I am tired.' → Lan said she was tired. Quy tắc: lùi thì (am → was, will → would, can → could), đổi tomorrow → the next day, yesterday → the day before, today → that day. Said + mệnh đề, không dùng ngoặc kép, không đảo ngữ.",
  quiz: [
  { q: "Lan said: 'I am tired.' → Lan said she ___ tired.", o: ["is", "was", "were"], a: 1, why: "Lùi thì: am → was." },
  { q: "He said: 'I will come tomorrow.' → He said he would come ___.", o: ["tomorrow", "the next day", "yesterday"], a: 1, why: "Tomorrow → the next day." },
  { q: "She said: 'I can swim.' → She said she ___ swim.", o: ["can", "could", "will"], a: 1, why: "Lùi thì: can → could." },
  { q: "They said: 'We finished yesterday.' → They said they ___ the day before.", o: ["finish", "had finished", "have finished"], a: 1, why: "Lùi thì quá khứ → quá khứ hoàn thành: had finished." },
  { q: "Câu nào đúng?", o: ["He said that he was busy.", "He said that he is busy.", "He said he are busy."], a: 0, why: "Câu tường thuật lùi thì: was." },
  { q: "Mai said: 'I am studying now.' → Mai said she ___ then.", o: ["is studying", "was studying", "studies"], a: 1, why: "Lùi thì tiếp diễn: is studying → was studying; now → then." }
  ] },
{ fam: "Câu điều kiện", level: "Band 6,0", name: "Câu điều kiện loại 1, 2, 3", hook: "“If it rains, we will stay home.” — Nếu trời mưa, chúng tôi sẽ ở nhà.", examples: ["If it rains, we will stay home. — Nếu trời mưa, chúng tôi sẽ ở nhà. (loại 1)", "If I had money, I would travel. — Nếu tôi có tiền, tôi sẽ đi du lịch. (loại 2)", "If I had studied, I would have passed. — Nếu tôi đã học, tôi đã đỗ. (loại 3)"], explain: "Ví dụ trước: Loại 1 (có thể xảy ra): 'If it rains, we will stay home.' Loại 2 (không thật ở hiện tại): 'If I were rich, I would travel.' Loại 3 (không thật ở quá khứ): 'If I had studied, I would have passed.' Quy tắc: loại 1: If + hiện tại, will; loại 2: If + quá khứ, would; loại 3: If + quá khứ hoàn thành, would have + phân từ 2.",
  quiz: [
  { q: "Điền đúng (loại 1): 'If it rains, we ___ home.'", o: ["stay", "will stay", "would stay"], a: 1, why: "Loại 1: will stay." },
  { q: "Điền đúng (loại 2): 'If I ___ rich, I would travel.'", o: ["am", "were", "was be"], a: 1, why: "Loại 2 với be dùng were." },
  { q: "Điền đúng (loại 3): 'If I had studied, I ___ passed.'", o: ["would pass", "would have passed", "will pass"], a: 1, why: "Loại 3: would have passed." },
  { q: "Điền đúng (loại 2): 'If she ___ more time, she would read more.'", o: ["has", "had", "will have"], a: 1, why: "If + quá khứ: had." },
  { q: "Điền đúng (loại 1): 'If you study hard, you ___ the exam.'", o: ["pass", "will pass", "would pass"], a: 1, why: "Loại 1: will pass." },
  { q: "Điền đúng (loại 3): 'If we ___ earlier, we would have caught the bus.'", o: ["left", "had left", "leave"], a: 1, why: "Loại 3: If + had left." }
  ] },
{ fam: "Mệnh đề quan hệ", level: "Band 6,0", name: "Mệnh đề quan hệ who, which, that, whose", hook: "“The girl who is singing is my sister.” — Cô gái đang hát là chị tôi.", examples: ["The girl who is singing is my sister. — Cô gái đang hát là chị tôi.", "The book which I bought is interesting. — Cuốn sách mà tôi mua rất thú vị.", "The man whose car is red is my teacher. — Người đàn ông có xe màu đỏ là thầy tôi."], explain: "Ví dụ trước: 'The man who lives next door is a teacher.' (Người đàn ông sống cạnh nhà là giáo viên.) 'The book which I bought is interesting.' Quy tắc: who cho người, which cho vật, that cho cả người và vật (trong mệnh đề hạn định), whose cho sở hữu (the man whose car...). Khi đại từ quan hệ làm tân ngữ, có thể bỏ: 'The book I bought is interesting.'",
  quiz: [
  { q: "Điền đúng: 'The man ___ lives next door is a teacher.'", o: ["who", "which", "whose"], a: 0, why: "Người: who." },
  { q: "Điền đúng: 'The book ___ I bought is interesting.'", o: ["who", "which", "whose"], a: 1, why: "Vật: which (hoặc that, hoặc bỏ)." },
  { q: "Điền đúng: 'The woman ___ car was stolen is my neighbour.'", o: ["who", "which", "whose"], a: 2, why: "Sở hữu: whose car." },
  { q: "Câu nào có thể bỏ đại từ quan hệ?", o: ["The book which I bought is interesting.", "The man who lives next door is a teacher.", "The girl whose bag is red is Lan."], a: 0, why: "Which làm tân ngữ (I bought) nên có thể bỏ: The book I bought..." },
  { q: "Điền đúng: 'This is the school ___ I studied.'", o: ["where", "who", "which"], a: 0, why: "Nơi chốn: where (hoặc that, hoặc bỏ)." },
  { q: "Điền đúng: '2020 was the year ___ I graduated.'", o: ["when", "where", "who"], a: 0, why: "Thời gian: when." }
  ] },
{ fam: "Mạo từ", level: "Band 5,5", name: "Mạo từ a, an, the và không mạo từ", hook: "“I saw a dog. The dog was black.” — Tôi thấy một con chó. Con chó đó màu đen.", examples: ["I saw a dog. — Tôi thấy một con chó.", "The dog was black. — Con chó đó màu đen.", "She plays the piano. — Cô ấy chơi đàn piano."], explain: "Ví dụ trước: 'I saw a dog. The dog was black.' (Lần đầu nhắc: a; lần sau nhắc lại: the.) 'She plays the piano.' (Nhạc cụ dùng the.) 'I like music.' (Danh từ trừu tượng chung: không mạo từ.) Quy tắc: a/an cho danh từ đếm được số ít chưa xác định (an trước nguyên âm); the cho danh từ đã xác định, duy nhất, hoặc cả nhóm; không mạo từ trước danh từ chung chung, môn học, ngôn ngữ, bữa ăn.",
  quiz: [
  { q: "Điền đúng: 'I saw ___ dog. ___ dog was black.'", o: ["a / The", "the / A", "an / The"], a: 0, why: "Lần đầu: a; nhắc lại: The." },
  { q: "Điền đúng: 'She plays ___ piano.'", o: ["a", "the", "không mạo từ"], a: 1, why: "Nhạc cụ: the piano." },
  { q: "Điền đúng: 'I like ___.' (âm nhạc nói chung)", o: ["a music", "the music", "music (không mạo từ)"], a: 2, why: "Danh từ trừu tượng chung: không mạo từ." },
  { q: "Điền đúng: 'He is ___ honest man.'", o: ["a", "an", "the"], a: 1, why: "Honest bắt đầu bằng nguyên âm /ɒ/ (h câm): an honest man." },
  { q: "Điền đúng: 'We have ___ breakfast at 7.'", o: ["a", "the", "không mạo từ"], a: 2, why: "Bữa ăn nói chung: không mạo từ." },
  { q: "Điền đúng: '___ sun rises in the east.'", o: ["A", "The", "Không mạo từ"], a: 1, why: "Vật duy nhất: The sun." }
  ] },
{ fam: "Giới từ thời gian", level: "Band 5,0", name: "Giới từ in, on, at với thời gian", hook: "“At 7 o'clock, on Monday, in June.” — Lúc 7 giờ, vào thứ Hai, vào tháng Sáu.", examples: ["At 7 o'clock. — Lúc 7 giờ.", "On Monday. — Vào thứ Hai.", "In June. — Vào tháng Sáu."], explain: "Ví dụ trước: 'at 7 a.m.', 'on Monday', 'in June', 'in 2020'. Quy tắc: at + giờ, lễ ngắn (at night, at Christmas); on + ngày, ngày trong tuần, ngày lễ cụ thể (on Monday, on 1 May); in + tháng, mùa, năm, buổi trong ngày (in June, in summer, in 2020, in the morning). Ngoại lệ: in the morning/afternoon/evening nhưng at night.",
  quiz: [
  { q: "Điền đúng: 'The class starts ___ 7 a.m.'", o: ["in", "on", "at"], a: 2, why: "Giờ dùng at." },
  { q: "Điền đúng: 'We meet ___ Monday.'", o: ["in", "on", "at"], a: 1, why: "Ngày trong tuần dùng on." },
  { q: "Điền đúng: 'She was born ___ June.'", o: ["in", "on", "at"], a: 0, why: "Tháng dùng in." },
  { q: "Điền đúng: 'He graduated ___ 2020.'", o: ["in", "on", "at"], a: 0, why: "Năm dùng in." },
  { q: "Điền đúng: 'I study ___ the morning.'", o: ["in", "on", "at"], a: 0, why: "Buổi sáng dùng in: in the morning." },
  { q: "Điền đúng: 'They sleep ___ night.'", o: ["in", "on", "at"], a: 2, why: "Ngoại lệ: at night." }
  ] },
{ fam: "So sánh", level: "Band 5,5", name: "So sánh hơn, nhất và ngang bằng", hook: "“Lan is taller than Mai. Lan is the tallest in class.” — Lan cao hơn Mai. Lan cao nhất lớp.", examples: ["Lan is taller than Mai. — Lan cao hơn Mai.", "Lan is the tallest in class. — Lan cao nhất lớp.", "Mai is as tall as Hoa. — Mai cao bằng Hoa."], explain: "Ví dụ trước: 'Lan is taller than Mai.' 'Lan is the tallest in the class.' 'Lan is as tall as Hoa.' Quy tắc: tính từ ngắn: -er/-est (taller, tallest); tính từ dài: more/most (more beautiful, the most beautiful); so sánh ngang bằng: as + tính từ + as; bất quy tắc: good → better → best, bad → worse → worst, far → farther/further → farthest/furthest.",
  quiz: [
  { q: "Điền đúng: 'Lan is taller ___ Mai.'", o: ["then", "than", "that"], a: 1, why: "So sánh hơn dùng than." },
  { q: "Điền đúng: 'Lan is the ___ in the class.'", o: ["tall", "taller", "tallest"], a: 2, why: "So sánh nhất: the tallest." },
  { q: "Điền đúng: 'This book is ___ interesting than that one.'", o: ["more", "most", "much"], a: 0, why: "Tính từ dài: more interesting." },
  { q: "Điền đúng: 'Lan is as tall ___ Hoa.'", o: ["than", "as", "like"], a: 1, why: "So sánh ngang bằng: as...as." },
  { q: "Điền đúng: 'This is the ___ film I have seen.'", o: ["good", "better", "best"], a: 2, why: "So sánh nhất của good: best." },
  { q: "Điền đúng: 'Today is worse ___ yesterday.'", o: ["then", "than", "that"], a: 1, why: "So sánh hơn của bad: worse than." }
  ] },
{ fam: "Động từ khuyết thiếu", level: "Band 5,5", name: "Động từ khuyết thiếu must, should, can, may", hook: "“You must stop. You can go now.” — Bạn phải dừng lại. Bạn có thể đi bây giờ.", examples: ["You must stop. — Bạn phải dừng lại.", "You can go now. — Bạn có thể đi bây giờ.", "You should study more. — Bạn nên học nhiều hơn."], explain: "Ví dụ trước: 'You must wear a helmet.' (Bắt buộc.) 'You should study more.' (Khuyên.) 'You can swim.' (Có thể.) 'You may go now.' (Được phép.) Quy tắc: must = bắt buộc; must not = cấm; should = nên; can = có thể/khả năng; may = được phép/có thể; don't have to = không bắt buộc. Sau khuyết thiếu luôn là động từ nguyên mẫu.",
  quiz: [
  { q: "Điền đúng: 'You ___ wear a helmet. It is the law.'", o: ["should", "must", "may"], a: 1, why: "Luật bắt buộc: must." },
  { q: "Điền đúng: 'You ___ study more if you want high marks.'", o: ["must", "should", "must not"], a: 1, why: "Lời khuyên: should." },
  { q: "Điền đúng: 'You ___ smoke here. It is forbidden.'", o: ["must not", "don't have to", "should"], a: 0, why: "Cấm: must not." },
  { q: "Điền đúng: 'You ___ come if you are busy. It is optional.'", o: ["must", "don't have to", "must not"], a: 1, why: "Không bắt buộc: don't have to." },
  { q: "Điền đúng: '___ I use your pen?'", o: ["Must", "Can", "Should"], a: 1, why: "Xin phép lịch sự: Can I...?" },
  { q: "Điền đúng: 'She ___ speak three languages.'", o: ["cans", "can", "canning"], a: 1, why: "Sau can là động từ nguyên mẫu: can speak." }
  ] },
{ fam: "Danh động từ và động từ nguyên mẫu", level: "Band 6,5", name: "Gerund và Infinitive sau động từ", hook: "“I enjoy swimming. I want to swim.” — Tôi thích bơi. Tôi muốn bơi.", examples: ["I enjoy swimming. — Tôi thích bơi.", "I want to swim. — Tôi muốn bơi.", "She decided to leave. — Cô ấy quyết định rời đi."], explain: "Ví dụ trước: 'I enjoy reading.' (enjoy + V-ing.) 'I want to read.' (want + to + V.) 'I stopped smoking.' (Ngừng hẳn việc hút.) 'I stopped to smoke.' (Dừng lại để hút.) Quy tắc: enjoy, avoid, finish, suggest, mind + V-ing; want, need, decide, hope, plan + to V; remember/forget + V-ing (đã làm) khác + to V (sẽ làm); stop + V-ing (ngừng hẳn) khác stop + to V (dừng để làm việc khác).",
  quiz: [
  { q: "Điền đúng: 'I enjoy ___.'", o: ["to read", "reading", "read"], a: 1, why: "Enjoy + V-ing: reading." },
  { q: "Điền đúng: 'I want ___ English well.'", o: ["to learn", "learning", "learn"], a: 0, why: "Want + to V: to learn." },
  { q: "Điền đúng: 'She decided ___ abroad.'", o: ["to study", "studying", "study"], a: 0, why: "Decide + to V: to study." },
  { q: "Điền đúng: 'He finished ___ the report.'", o: ["to write", "writing", "write"], a: 1, why: "Finish + V-ing: writing." },
  { q: "'I stopped smoking.' nghĩa là:", o: ["Tôi đã ngừng hẳn việc hút thuốc.", "Tôi dừng lại để hút thuốc.", "Tôi muốn hút thuốc."], a: 0, why: "Stop + V-ing = ngừng hẳn việc đó." },
  { q: "'I stopped to smoke.' nghĩa là:", o: ["Tôi đã ngừng hẳn việc hút thuốc.", "Tôi dừng việc đang làm để hút thuốc.", "Tôi muốn bỏ thuốc."], a: 1, why: "Stop + to V = dừng việc đang làm để làm việc khác." }
  ] }
];
